    if ((wheels == NULL) || (wheel_torque == NULL) || (momentum == NULL) || 
        (body_torque == NULL) || (mechanical_power == NULL) || (bus_power == NULL)) {
        return ADCS_E_NULL;
    }

    if ((count < 1) || (count > 16) || (!isfinite(efficiency)) || (efficiency <= 0.0) || (efficiency > 1.0)) {
        return ADCS_E_RANGE;
    }

    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    *body_torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    *mechanical_power = 0.0;
    *bus_power = 0.0;

    for (size_t i = 0; i < count; i++) {
        adcs_vec3_t axis;
        double inertia = wheels[i].inertia_kg_m2;
        double speed = wheels[i].speed_rad_s;
        double torque = wheel_torque[i];

        if ((!isfinite(inertia)) || (!isfinite(speed)) || (!isfinite(torque))) {
            return ADCS_E_RANGE;
        }

        adcs_status_t status = adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis);
        if (status != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        double h_i = inertia * speed;
        adcs_vec3_t term_h = adcs_vec3_scale(&axis, h_i);
        *momentum = adcs_vec3_add(momentum, &term_h);

        adcs_vec3_t term_tau = adcs_vec3_scale(&axis, -torque);
        *body_torque = adcs_vec3_add(body_torque, &term_tau);

        double p_mech = torque * speed;
        *mechanical_power += p_mech;

        if (p_mech > 0.0) {
            *bus_power += p_mech / efficiency;
        }
    }

    return ADCS_OK;
}

