    if (!isfinite(efficiency) || (efficiency <= 0.0) || (efficiency > 1.0)) {
        return ADCS_E_RANGE;
    }

    status = adcs_wheel_momentum(wheels, count, momentum);
    if (status != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    *body_torque = zero_vec;
    *mechanical_power = 0.0;
    *bus_power = 0.0;

    for (i = 0; i < count; i++) {
        if (!isfinite(wheel_torque[i])) {
            return ADCS_E_RANGE;
