        if (status != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        adcs_vec3_t torque_term = adcs_vec3_scale(&normalized_axis, -wheel_torque[i]);
        *body_torque = adcs_vec3_add(body_torque, &torque_term);

        mech_power_term = wheel_torque[i] * wheels[i].speed_rad_s;
        *mechanical_power += mech_power_term;

        if (mech_power_term > 0.0) {
